"""Authored Bet Din hearings 65-84 (BD-171-191, excluding already used BD-173)."""

def F(n, book, slug, flag, order, title, scene, choices, risks, outcomes,
      truth, falsity, ref, question, pillar="stability"):
    return dict(n=n, book=book, slug=slug, flag=flag, order=order, title=title,
                scene=scene, a=choices[0], b=choices[1], c=choices[2],
                a_tt=risks[0], b_tt=risks[1], c_tt=risks[2],
                out1=outcomes[0], out2=outcomes[1], out3=outcomes[2],
                true=truth, false=falsity,
                source=f"Cite a mastered {order.title()} work and examine the evidence.",
                source_tt=f"Mishnah {ref} gives the judges a textual point of reference. It cannot establish {question}.",
                combo="Have a scholar and steward inspect the disputed evidence together.",
                combo_tt=f"The judges preserve both parties' interests while checking {question}.",
                one=f"The immediate ruling costs 8 {pillar.title()} and carries the larger fact risk.",
                two=f"Inquiry costs 4 {pillar.title()} while the court keeps the issue open.",
                three=f"The quick final settlement costs 2 {pillar.title()} but may be overbroad.",
                log=f"[CHARACTER.GetTitledFirstName] ruled on [TARGET_CHARACTER.GetFirstName]'s {title.lower()} dispute.",
                pillar=pillar)

EXTRA_CASES_4 = [
 F(65,"BD-171","inherited_seat","seat_communal","moed","The Synagogue Seat Inherited",
   "[kbd_litigant_a.GetFirstName] claims the honored seat once used by a parent. [kbd_litigant_b.GetFirstName] speaks for members who want seats assigned anew. The old contribution book names the family, but not whether its gift bought lasting use. The next service is near, and a public quarrel over one bench threatens the prayer room.",
   ["Let the heir keep the seat.","Assign a temporary place and read the contribution book.","Redistribute every honored seat now."],
   ["The family keeps continuity, but a communal seat may become private without cause.","The court buys time while checking the gift and current seating needs.","A fresh allocation may erase a genuine family grant."],
   ["The court reserves the seat for the heir.","The court gives a temporary place and asks for the original gift terms.","The court opens all honored seats to reassignment."],
   "The gift supported the synagogue generally; it did not grant a permanent seat. Sole inheritance narrowed common space.",
   "The deed expressly reserved the seat to the family. A blanket redistribution broke that term.",
   "Megillah 3:1","the gift's seating term"),
 F(66,"BD-172","holiday_wine","handling_proved","moed","The Holiday Wine Scandal",
   "[kbd_litigant_a.GetFirstName] sold wine for the festival and says every jar remained under proper care. [kbd_litigant_b.GetFirstName] says an unauthorized handler opened several jars at the dock. No one marked which ones. The court must protect the meal without ruining sound stock on rumor.",
   ["Release every jar for festival use.","Separate the jars and hear dock witnesses.","Reject the whole shipment."],
   ["Families get wine promptly, but proven handling could make the approval unsound.","Inspection and substitution cost time and supplies.","Caution is simple, but sound jars would be wasted."],
   ["The court releases the shipment.","The court separates jars by dock record and asks witnesses what they saw.","The court rejects every jar in the shipment."],
   "Dock testimony identifies opened jars. Unqualified approval ignored a real concern.",
   "The seals and witnesses show the shipment stayed closed. Rejection wasted usable wine.",
   "Pesachim 2:1","which jars were opened","greatness"),
 F(67,"BD-174","cracked_shofar","crack_decisive","moed","The Shofar With a Crack",
   "[kbd_litigant_a.GetFirstName] defended the shofar used at the last service. [kbd_litigant_b.GetFirstName] says a crack crossed the horn before the first blast and that a warning was ignored. The horn is still in its case. The court can examine it, but a public verdict will also judge the appointed blower's care.",
   ["Confirm the service without examining the horn.","Inspect the crack and hear those who warned the blower.","Declare the instrument unfit and censure the blower."],
   ["Reassurance comes quickly, but a decisive crack would be missed.","An examination costs time and public patience.","A harmless surface line could become an unjust public rebuke."],
   ["The court confirms the service and dismisses the complaint.","The court examines the horn and hears when the crack was seen.","The court censures the blower and rejects the instrument."],
   "The crack runs through the sounding part. A ruling without inspection overlooked it.",
   "The line is superficial and does not affect the sounding part. Censure was premature.",
   "Rosh Hashanah 3:6","the crack's extent","greatness"),
 F(68,"BD-175","sabbath_stall","business_continued","moed","The Sabbath Market Stall",
   "[kbd_litigant_a.GetFirstName] owns a stall left with a non-Jewish attendant on Sabbath. [kbd_litigant_b.GetFirstName] speaks for rivals who say the owner still directed sales through a messenger. The stall's agreement names rent, not who sets prices. The court must distinguish a closed owner's business from a disguised open one.",
   ["Accept the attendant's arrangement as sufficient.","Inspect contracts, messages and actual sales.","Forbid every such stall arrangement."],
   ["Trade continues, but hidden directions could make the arrangement a fiction.","The court pays for an inquiry without closing all trade.","A blanket ban may punish lawful independent leases."],
   ["The court permits the stall to continue under its current agreement.","The court calls the attendant and reads the week's messages and accounts.","The court bans all attendant-run stalls on Sabbath."],
   "Messages show the owner set prices and ordered sales that day. The paper lease concealed continuing business.",
   "The attendant leased the stall independently and kept its gains. A blanket ban reached beyond this dispute.",
   "Shabbat 7:2","who directed the Sabbath sales"),
 F(69,"BD-176","cantor_prior_ban","ban_still_active","nezikin","The Cantor's Prior Ban",
   "[kbd_litigant_a.GetFirstName] speaks for a visiting cantor invited to lead services. [kbd_litigant_b.GetFirstName] says another city placed him under a ban that was never lifted. The letter offered as proof bears no date of release. The community needs a voice for the coming festival, but a rumor can stain a person for years.",
   ["Seat the cantor and dismiss the allegation.","Use a substitute and ask the issuing court for its record.","Bar the cantor permanently from the lectern."],
   ["The festival has a leader, but an active ban could be ignored.","A substitute and inquiry cost money and patience.","A lifted ban would make permanent exclusion unjust."],
   ["The court confirms the cantor's appointment.","The court arranges a substitute and sends for the other city's record.","The court bars the cantor from future service."],
   "The issuing court says its ban remains active. Immediate confirmation ignored a live sanction.",
   "The issuing court records a formal release. Permanent exclusion prolonged a spent penalty.",
   "Sanhedrin 3:3","whether the prior ban remains in force"),
 F(70,"BD-177","reader_wages","service_prevented","moed","The Torah Reader's Wage",
   "[kbd_litigant_a.GetFirstName] speaks for officers who withheld a Torah reader's holiday wage after the synagogue closed for repairs. [kbd_litigant_b.GetFirstName] says the reader stood ready and could not take other work. The contract names a season, not a number of readings. The court must assign the cost of a closure no one planned.",
   ["Withhold all wages for missed readings.","Pay an advance and examine contract and closure dates.","Pay the full season without inquiry."],
   ["The treasury is protected, but a reader prevented from working may have earned the wage.","The court keeps the reader solvent while checking the promised service.","Full payment may ignore days when the reader was unavailable."],
   ["The court denies payment for the closed period.","The court advances wages and reads the contract against the repair record.","The court pays the whole holiday season."],
   "The reader was ready each scheduled day; the closure alone prevented service. Full withholding denied contracted pay.",
   "The reader left town for part of the season. Automatic full payment ignored missed availability.",
   "Megillah 4:4","the reader's availability and contract","prosperity"),
 F(71,"BD-178","doubtful_fowl","injury_disqualifies","kodashim","The Doubtful Fowl",
   "[kbd_litigant_a.GetFirstName] sold a slaughtered bird before the inspector arrived. [kbd_litigant_b.GetFirstName] saw an injury and wants the sale undone. The bird is preserved, but every delay makes it less useful. The court needs an actual examination, not a victory for the loudest market voice.",
   ["Approve the sale on the butcher's assurance.","Hold the bird for a qualified inspection.","Refund the buyer and condemn the bird now."],
   ["The market moves quickly, but a disqualifying injury could be missed.","Inspection costs time while preserving the evidence.","A harmless mark could make condemnation wasteful and unfair."],
   ["The court approves the sale without opening the bird.","The court holds the bird for the inspector and records the seller's account.","The court refunds the buyer and rejects the bird."],
   "The inspector finds a disqualifying injury. Unexamined approval was unsound.",
   "The mark is harmless and the cut sound. Immediate condemnation wasted food.",
   "Chullin 2:1","the bird's actual injury","greatness"),
 F(72,"BD-179","paschal_oven","oven_unsound","moed","The Paschal Oven",
   "[kbd_litigant_a.GetFirstName] baked festival food in a shared oven and says it was prepared correctly. [kbd_litigant_b.GetFirstName] claims an earlier use made the oven unsuitable and asks for replacement. The baker's fire is out, but the oven and utensils remain. The court must decide before the meal is served.",
   ["Serve the food without checking the oven.","Inspect the oven and prepare a replacement meal if needed.","Discard every batch from the oven."],
   ["Families keep their meal, but an unsuitable oven could be overlooked.","Inspection and a backup meal cost scarce time and flour.","A sound oven would make blanket disposal wasteful."],
   ["The court releases the baked food.","The court examines the oven and arranges a backup meal.","The court discards every batch and orders replacements."],
   "The oven's previous use left a disqualifying condition. Quick release ignored it.",
   "The oven was prepared properly. Disposal needlessly deprived households of their food.",
   "Pesachim 1:1","the oven's actual preparation","greatness"),
 F(73,"BD-180","ownerless_book","owner_mark_found","nezikin","The Ownerless Prayer Book",
   "[kbd_litigant_a.GetFirstName] cares for a prayer manuscript recovered from a ruined house and wants it placed in the synagogue. [kbd_litigant_b.GetFirstName] says a displaced family may still own it. A faint mark appears inside the cover; no one has read it. The book should be kept safe while ownership is sought.",
   ["Enter the book into communal property now.","Preserve it and search for the marked owner.","Give it to the claimant without checking the mark."],
   ["Worshippers gain a book, but a readable owner mark could make that a taking.","The court protects the manuscript while tracing its owner.","A false claimant could receive a valuable book."],
   ["The court catalogs the manuscript as synagogue property.","The court protects the book and asks a scribe to read its mark.","The court hands the book to the claimant."],
   "The mark names a displaced family's owner. Immediate communal claim would have erased that right.",
   "The mark belongs to an unrelated former copyist. Unchecked delivery would give the book to the wrong person.",
   "Bava Metzia 2:2","the manuscript's owner mark","prosperity"),
 F(74,"BD-181","scribes_name","errors_uncorrected","moed","The Scribe's Incorrect Divine Name",
   "[kbd_litigant_a.GetFirstName] copied a scroll and says several mistaken words can be corrected. [kbd_litigant_b.GetFirstName] represents buyers who found repeated errors, including in a divine name. The scroll is expensive and the festival near. The court must protect the text without treating a scribe's promise as an inspection.",
   ["Accept the scribe's repair plan without examination.","Have qualified readers mark errors before any use.","Reject the entire scroll and bar the scribe."],
   ["The scroll stays available, but an uncorrectable error could remain.","Careful review costs money and may delay use.","A repairable text could be lost and a craftsperson unjustly punished."],
   ["The court permits the scribe to correct the scroll immediately.","The court commissions a full reading and records which errors can be repaired.","The court rejects the scroll and suspends the scribe."],
   "The readers find an error that the proposed repair cannot cure. Unchecked use was unsound.",
   "The readers find only repairable errors. Blanket rejection was disproportionate.",
   "Megillah 3:1","which errors this scroll actually contains","greatness"),
 F(75,"BD-182","festival_charity","food_earmarked","zeraim","The Festival Charity Meal",
   "[kbd_litigant_a.GetFirstName] keeps a food fund and wants to buy splendid ritual furnishings before the festival. [kbd_litigant_b.GetFirstName] speaks for families expecting a communal meal from that money. The donor's note is short, and the market is already setting prices. Prestige and hunger both have voices in the room.",
   ["Buy the furnishings from the food chest.","Feed families now and inspect the donor's note.","Cancel all purchases and hoard the fund."],
   ["The festival gains splendor, but earmarked food may be lost.","A meal and inquiry cost resources while preserving the donor's intent.","If the gift was flexible, hoarding it serves neither hunger nor worship."],
   ["The court authorizes the furnishings.","The court provides a modest meal and reads the donor's note.","The court closes the fund for the season."],
   "The note earmarks the money for food. Furnishings would divert the gift.",
   "The note permits food and furnishings. Closing the chest entirely wasted a useful gift.",
   "Peah 8:7","the donor's actual designation","prosperity"),
 F(76,"BD-183","fast_day_custom","local_custom_binding","moed","The Conflicting Fast-Day Customs",
   "[kbd_litigant_a.GetFirstName] speaks for local elders who announce one practice for the coming fast. [kbd_litigant_b.GetFirstName] speaks for refugees whose former community observed another. Both groups will gather in the same synagogue. The elders have an old minute book, but its final page is missing.",
   ["Impose the elders' practice on everyone.","Keep separate services while checking the communal minute.","Replace the local practice with the refugees' version."],
   ["One service is simple, but a binding accommodation may be ignored.","Parallel services cost effort while the community checks its record.","A valid local rule may be overturned for newcomers without consent."],
   ["The court orders one service under the elders' custom.","The court arranges separate services and seeks the missing minute.","The court adopts the refugees' practice for all."],
   "The missing minute grants newcomers their own observance. Forced uniformity broke that agreement.",
   "The minute confirms the established local practice as binding for shared services. Replacing it ignored the pact.",
   "Ta'anit 3:1","the community's agreement about this fast"),
 F(77,"BD-184","private_ban","warning_absent","nashim","The Rav Who Issued a Private Ban",
   "[kbd_litigant_a.GetFirstName] speaks for a scholar who sanctioned a tradesman after an insult. [kbd_litigant_b.GetFirstName] says there was no warning or communal hearing. Customers have stopped visiting his shop. The court must protect its discipline from private anger while allowing a genuine public wrong to be heard.",
   ["Uphold the scholar's ban immediately.","Pause the ban and hold a hearing with witnesses.","Void the ban and forbid any new complaint."],
   ["Authority is defended, but a ban without notice may be personal retaliation.","A hearing costs time while the tradesman's business remains protected.","A serious public offense could be buried by a blanket dismissal."],
   ["The court enforces the existing ban.","The court pauses the sanction and calls both sides with witnesses.","The court voids the ban and closes the matter."],
   "No warning or hearing preceded the sanction. Enforcement turned private offense into court power.",
   "A prior hearing and warning are documented. Closing every complaint ignored that record.",
   "Nedarim 1:1","the warning and hearing actually given"),
 F(78,"BD-185","widows_pledge","consent_uncertain","nashim","The Widow's Public Charity Pledge",
   "[kbd_litigant_a.GetFirstName] speaks for collectors who recorded a widow's large festival pledge. [kbd_litigant_b.GetFirstName] says she misunderstood the amount and cannot pay without selling household tools. The crowd cheered at the time; the written note has no witness to the sum. The court must protect both charity and informed consent.",
   ["Collect the full public pledge now.","Provide interim charity and hear the widow and witnesses privately.","Cancel the pledge entirely."],
   ["The fund receives money, but an uncomprehended amount could ruin the household.","The poor are served while the court checks what was actually promised.","A clear, affordable pledge could be discarded without cause."],
   ["The court orders full collection.","The court advances relief and hears the widow away from the crowd.","The court releases her from the entire pledge."],
   "Witnesses disagree on the amount, and the widow understood a smaller gift. Full collection exceeded her undertaking.",
   "Two witnesses confirm the full amount and her clear assent. Total cancellation ignored a deliberate pledge.",
   "Nedarim 1:1","the widow's understanding and means","prosperity"),
 F(79,"BD-186","changed_witness","first_account_false","nezikin","The Witness Who Changed His Story",
   "[kbd_litigant_a.GetFirstName] relies on a witness who described a debt one way at the first hearing. [kbd_litigant_b.GetFirstName] produces his second account, which gives a different date. The witness says memory improved; each litigant calls the other version a lie. The court needs the original notes before treating inconsistency as proof of fraud.",
   ["Use the first account and rule now.","Compare both records and question the witness again.","Reject all testimony from the witness."],
   ["The case closes, but a false first date could distort the debt.","A new hearing costs time while testing the discrepancy.","An innocent correction could be discarded with the falsehood."],
   ["The court relies on the first account.","The court puts both records before the witness and asks for the change.","The court excludes all of his testimony."],
   "The first clerk wrote the wrong date; the witness corrected it promptly. Ruling on the first account was unsound.",
   "Both accounts concern separate transactions. Blanket exclusion lost useful testimony.",
   "Sanhedrin 3:6","why the two accounts differ"),
 F(80,"BD-187","judges_relative","kinship_close","nezikin","The Judge's Brother-in-Law",
   "[kbd_litigant_a.GetFirstName] asks a judge to remain on a property panel despite a claimed family tie to one party. [kbd_litigant_b.GetFirstName] says the tie is close enough to cast doubt on every ruling. The court has two other qualified judges, but changing the panel delays a hearing already set.",
   ["Keep the judge and hear the case today.","Verify kinship and use a temporary substitute.","Dismiss the whole panel and start over."],
   ["The hearing proceeds, but a close relationship may taint the judgment.","A substitute costs time while a specific conflict is checked.","If the claimed tie is distant, dissolving the panel wastes sound preparation."],
   ["The court keeps the challenged judge.","The court checks the family link and seats a temporary substitute.","The court dissolves the whole panel."],
   "The judge is closely related by marriage to a party. Keeping him jeopardized the hearing's fairness.",
   "The families share only a distant name, not a disqualifying tie. Dissolving the panel was needless.",
   "Sanhedrin 3:4","the actual relationship between judge and party"),
 F(81,"BD-188","distant_witness","letter_unauthenticated","nezikin","The Missing Witness Across the Border",
   "[kbd_litigant_a.GetFirstName] offers a letter from a witness in a distant city to prove a merchant debt. [kbd_litigant_b.GetFirstName] disputes its handwriting and asks for sworn testimony. The witness cannot travel before the caravan leaves. The court must preserve the claim without turning an unverified letter into a verdict.",
   ["Accept the letter and award the debt now.","Secure the claim and seek an authenticated deposition.","Reject distant testimony altogether."],
   ["The claimant is paid, but a forged letter could determine the case.","Security and a messenger cost money while testimony is checked.","A genuine witness may be silenced by a blanket rejection."],
   ["The court awards the debt on the letter.","The court secures the claim and asks the distant court to certify the testimony.","The court rejects the letter and closes the claim."],
   "The distant court cannot confirm the handwriting. An immediate award rested on uncertain proof.",
   "The court certifies the witness and seal. Blanket rejection lost reliable testimony.",
   "Sanhedrin 3:6","the letter's writer and certification"),
 F(82,"BD-189","fear_confession","threat_proved","nezikin","The Confession Extracted in Fear",
   "[kbd_litigant_a.GetFirstName] asks the court to enforce a thief's signed admission. [kbd_litigant_b.GetFirstName] says officers threatened a harsh sanction before the signature and withdraws the words. Missing goods still need to be found. The court must examine the pressure before treating a confession as proof.",
   ["Enforce the admission immediately.","Set it aside temporarily and investigate goods and threats.","Dismiss the theft claim entirely."],
   ["The claimant gets a quick answer, but a coerced admission may be worthless.","An inquiry costs time while preserving independent evidence.","A free and accurate admission could be lost by closing the case."],
   ["The court enforces the signed admission.","The court checks the officers' conduct and searches for independent proof.","The court dismisses the accusation."],
   "Officers threatened the accused before the signature. Immediate enforcement relied on fear.",
   "The admission was made freely and the goods match its account. Dismissal ignored sound evidence.",
   "Sanhedrin 4:1","whether threats preceded the admission"),
 F(83,"BD-190","false_oath","words_misheard","nezikin","The False Oath Allegation",
   "[kbd_litigant_a.GetFirstName] says a debtor swore that a loan was repaid. [kbd_litigant_b.GetFirstName] says the words referred to a different payment and were heard through a crowded room. Two witnesses remember different phrases. The court must settle the debt without declaring a false oath on uncertain hearing.",
   ["Treat the oath as false and collect the debt.","Hear the witnesses separately and compare both payments.","Clear the debtor and cancel the debt."],
   ["Collection is quick, but misheard words could brand an honest person a liar.","A careful hearing costs time and court resources.","If the debt remains unpaid, complete release wrongs the lender."],
   ["The court declares the oath false and orders payment.","The court separates witnesses and traces the two payments.","The court clears the debtor and cancels the claim."],
   "The oath was about another payment. A false-oath ruling misread the speaker's words.",
   "Both records show this loan remained unpaid. Cancelling it rewarded evasion.",
   "Shevuot 7:1","the words used and the debt they concerned"),
 F(84,"BD-191","missing_seal","seal_required","nezikin","The Missing Court Seal",
   "[kbd_litigant_a.GetFirstName] produces a deed for a house; [kbd_litigant_b.GetFirstName] produces another. The first has witnesses but no court seal. Both parties say the seller chose them. The local clerk can compare the forms, but the house is already being repaired by one claimant.",
   ["Accept the unsealed deed and settle possession.","Hold the house and examine witnesses and district forms.","Reject the unsealed deed outright."],
   ["Repairs can continue, but a required missing seal may invalidate the claim.","Inquiry costs money while protecting the house.","A seal-free deed may still be valid under the district's rules."],
   ["The court accepts the unsealed deed.","The court preserves the house while a clerk checks both deeds and witnesses.","The court rejects the unsealed deed."],
   "District practice required that seal for this transfer. Immediate acceptance overlooked a decisive omission.",
   "The seller's witnesses confirm a valid unsealed transfer. Automatic rejection ignored their proof.",
   "Bava Batra 10:1","the district's seal practice and these witnesses"),
]
